    },
    [68] = {
      beijing = 8040,
      dialog = 3,
      music = "PW_1_Relax",
      renwu = "npc",
      sentence = "This would be the liveliest event of the whole year. The streets were filled with vendors and journeymen selling all kinds of weird and wonderful objects.",
      next = {69}
    },
    [69] = {
      beijing = 8040,
      dialog = 3,
      music = "PW_1_Relax",
      renwu = "npc",
      sentence = "I picked a stall at random and dragged him over to take a closer look.",
      next = {70}
    },
    [70] = {
