      renwu = "npc",
      role1 = 180000,
      role2 = 102101,
      role3 = 102201,
      role6 = 1795003,
      ruchang = -1,
      sentence = "The doll was wearing a brightly colored cape and its horns and tail were stuffed tightly with cotton padding. I picked one up and gave it to Victor. He looked at it suspiciously.",
