    },
    [82] = {
      beijing = 8040,
      dialog = 3,
      music = "PW_1_Relax",
      renwu = "npc",
      sentence = "Maybe it was my imagination, but Victor seemed to slow his steps to match his own pace with mine.",
      next = {83}
    },
    [83] = {
      beijing = 8040,
      dialog = 3,
      music = "PW_1_Relax",
      renwu = "npc",
      sentence = "He'd spent centuries alone in the forest. It was very unlikely he had ever seen anything quite as noisy as this.",
      next = {84}
    },
    [84] = {
      beijing = 8040,
      dialog = 3,
      music = "PW_1_Relax",
      renwu = "npc",
      sentence = "I promised myself I would use this day to give him a taste of mortal life, in all its noisy, jocular chaos.",
      next = {85}
    },
    [85] = {
      beijing = 8040,
      dialog = 3,
      music = "PW_1_Relax",
      renwu = "npc",
      sentence = "The street was very long, and the stalls went on for many hundreds of yards. We took our time looking at all the wares, soaking up all the sights and sounds of the fair.",
      next = {86}
    },
    [86] = {
      beijing = 8040,
      dialog = 3,
      music = "PW_1_Relax",
      renwu = "npc",
      sentence = "Imagine the high and mighty Divine Guardian, exploring the streets with me, squinting in the smoke and aroma of strange candies.",
      next = {87}
    },
    [87] = {
      beijing = 8040,
      dialog = 3,
      music = "PW_1_Relax",
      renwu = "npc",
      sentence = "Occasionally he appeared reluctant, but to my surprise he did not refuse. Perhaps it was the smoke from the fireworks, but for a while his true identity slipped my mind.",
      next = {88}
    },
    [88] = {
      beijing = 8041,
      dialog = 3,
      music = "PW_1_Relax",
      renwu = "npc",
      sentence = "Time passed and we eventually found ourselves at the end of the street. A small brook cut across the path and people lit sky lanterns along the banks.",
      next = {89}
    },
    [89] = {
      beijing = 8041,
      dialog = 2,
